n_gimcheon", "name": "국립김천숲속야영장 반려견놀이터 배변수거함", "description": "경상북도 김천시 대덕면 조룡길 865 · 공식 시설 정보에서 대형·소형 반려견놀이터와 배변수거함을 확인했습니다. 야영장 예약·입장 조건이 있으며 외부 산책객 이용 가능 여부는 관리소에 먼저 문의하세요. · 시설 대표 위치이며 수거함 자체의 정확한 좌표는 공개 자료로 확인되지 않았습니다. 현장에서 안내판과 설치 위치·작동 상태를 확인하세요.", "lat": 35.94890789, "lng": 127.95428978, "status": "approved", "author": "발자국 자료 조사"}]$payload$::jsonb)
 AS x(id text,name text,description text,lat double precision,lng double precision,status text,author text)
), inserted AS (
 INSERT INTO public.bins(id,name,description,lat,lng,status,author,owner_id)
 SELECT i.id,i.name,i.description,i.lat,i.lng,i.status,i.author,NULL FROM incoming i
 WHERE NOT EXISTS (SELECT 1 FROM public.bins b WHERE regexp_replace(b.name,'\s','','g')=regexp_replace(i.name,'\s','','g'))
 ON CONFLICT (id) DO NOTHING
 RETURNING id,name
)
SELECT * FROM inserted ORDER BY id;
